import {useEffect,useState} from 'react';
import {Activity,AlertTriangle,BarChart3,CalendarRange,RefreshCw,UsersRound,WalletCards} from 'lucide-react';
import {getPracticeAnalytics} from '../../lib/practiceOperationsApi';

const presets=[['7d','7 days'],['30d','30 days'],['90d','90 days'],['this_month','This month'],['last_month','Last month']];
const money=(value,currency='INR')=>value==null?'—':new Intl.NumberFormat(undefined,{style:'currency',currency}).format(value/100);
const pct=value=>value==null?'—':`${value}%`;
function MetricCard({label,value,detail,Icon=Activity}){return <article className="rounded-2xl border border-slate-200 bg-white p-4"><Icon size={18} className="text-blue-700"/><p className="mt-4 text-2xl font-bold text-slate-950">{value}</p><p className="mt-1 text-sm font-semibold text-slate-700">{label}</p>{detail&&<p className="mt-1 text-xs text-slate-500">{detail}</p>}</article>}
function Distribution({title,items}){const total=items.reduce((sum,item)=>sum+Number(item[1]||0),0);return <section className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="font-bold">{title}</h3><p className="mt-1 text-xs text-slate-500">{total} records in this distribution</p><div className="mt-5 space-y-3">{items.map(([label,value])=><div key={label}><div className="flex justify-between text-sm"><span>{label.replaceAll('_',' ')}</span><strong>{value}</strong></div><div className="mt-1 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-blue-600" style={{width:`${total?Math.max(4,(value/total)*100):0}%`}}/></div></div>)}</div>{total===0&&<p className="mt-4 rounded-xl bg-slate-50 p-3 text-sm text-slate-500">Confirmed empty for this period.</p>}</section>}

export function ExternalPracticeAnalytics({activeClientCount}){
  const[preset,setPreset]=useState('30d'),[state,setState]=useState('loading'),[data,setData]=useState(null),[message,setMessage]=useState('');
  const load=async()=>{setState('loading');setMessage('');try{setData(await getPracticeAnalytics(preset));setState('ready')}catch(error){setMessage(error.message||'Analytics could not be loaded.');setState('error')}};
  useEffect(()=>{void load()},[preset]);
  if(state==='loading')return <section aria-label="Loading practice analytics" className="grid min-h-64 place-items-center rounded-3xl border bg-white"><Activity className="animate-pulse text-blue-700"/><span className="sr-only">Loading analytics</span></section>;
  if(state==='error')return <section role="alert" className="rounded-3xl border border-red-200 bg-red-50 p-6 text-red-900"><AlertTriangle/><h2 className="mt-3 text-xl font-bold">Analytics unavailable</h2><p className="mt-2 text-sm">{message} No unavailable metric has been converted to zero.</p><button onClick={load} className="mt-5 min-h-11 rounded-xl bg-red-900 px-4 font-semibold text-white"><RefreshCw className="mr-2 inline" size={16}/>Retry</button></section>;
  const business=data.business,operations=data.operations,currency=business.currency||'INR';
  return <div className="space-y-5"><header className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Insights</p><h2 className="mt-1 text-3xl font-bold tracking-tight">Practice analytics</h2><p className="mt-2 text-sm text-slate-600">Business, operations, engagement, outcomes, and team workload from governed practice data.</p></div><label className="text-sm font-semibold">Period<select value={preset} onChange={event=>setPreset(event.target.value)} className="ml-2 min-h-11 rounded-xl border border-slate-200 bg-white px-3">{presets.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label></header>
    {data.unavailable?.length>0&&<p role="status" className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">Partial data: {data.unavailable.map(item=>item.replaceAll('_',' ')).join(', ')} unavailable. Dashes are shown instead of false zeroes.</p>}
    <nav aria-label="Analytics sections" className="flex gap-2 overflow-x-auto">{['Overview','Clients','Sessions','Revenue','Engagement','Operations','Outcomes','Team'].map(item=><a key={item} href={`#analytics-${item.toLowerCase()}`} className="min-h-11 shrink-0 rounded-xl border bg-white px-4 py-3 text-xs font-semibold">{item}</a>)}</nav>
    <section id="analytics-overview" aria-label="Practice overview" className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Active clients" value={activeClientCount} detail="Authoritative current client roster" Icon={UsersRound}/><MetricCard label="Completed sessions" value={business.completed_sessions} detail={`${business.total_sessions} total`} Icon={CalendarRange}/><MetricCard label="Paid amount" value={money(business.paid_amount_minor,currency)} Icon={WalletCards}/><MetricCard label="Outstanding" value={money(business.outstanding_amount_minor,currency)} Icon={BarChart3}/></section>
    <div className="grid gap-5 xl:grid-cols-2"><Distribution title="Session status" items={[["COMPLETED",business.completed_sessions],["CANCELLED",business.cancelled_sessions],["NO_SHOW",business.no_shows]]}/><Distribution title="Engagement — operational, not medical risk" items={Object.entries(data.engagement).filter(([,value])=>typeof value==='number')}/></div>
    <section id="analytics-operations" className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><MetricCard label="Session utilisation" value={pct(business.session_utilisation)}/><MetricCard label="Follow-up completion" value={pct(operations.followups.rate)} detail={`${operations.followups.completed}/${operations.followups.total}`}/><MetricCard label="Task completion" value={pct(operations.tasks.rate)} detail={`${operations.tasks.completed}/${operations.tasks.total}`}/><MetricCard label="Homework completion" value={pct(operations.homework.rate)} detail={`${operations.homework.completed}/${operations.homework.total}`}/><MetricCard label="Assessment completion" value={pct(operations.assessments.rate)}/><MetricCard label="Automation success" value={pct(operations.automation.execution_rate)}/><MetricCard label="Automation failure" value={pct(operations.automation.failure_rate)}/><MetricCard label="Waitlist" value={operations.waitlist_size}/></section>
    <section id="analytics-revenue" className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><MetricCard label="Invoice total" value={money(business.invoice_total_minor,currency)}/><MetricCard label="Average invoice" value={money(business.average_invoice_value_minor,currency)}/><MetricCard label="Overdue" value={money(business.overdue_amount_minor,currency)}/><MetricCard label="Packages ending soon" value={business.packages_ending_soon}/></section>
    <section id="analytics-outcomes" className="rounded-3xl border bg-white p-5"><h3 className="font-bold">Governed outcome analytics</h3><p className="mt-1 text-sm text-slate-500">Aggregates require at least {data.outcomes.minimum_cohort_size} clients. No diagnosis or treatment-effect language is generated.</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{data.outcomes.items.map(item=><article key={item.code} className="rounded-xl bg-slate-50 p-4"><strong>{item.label}</strong><p className="mt-1 text-sm text-slate-600">{item.state==='INSUFFICIENT_COHORT'?`Insufficient cohort (${item.cohort_size}/${data.outcomes.minimum_cohort_size})`:`${item.observations} observations · ${item.direction||'direction not configured'}`}</p></article>)}{!data.outcomes.items.length&&<p className="text-sm text-slate-500">Confirmed empty: no governed outcome observations in this period.</p>}</div></section>
    <section id="analytics-team" className="rounded-3xl border bg-white p-5"><h3 className="font-bold">Practitioner workload</h3>{data.team.restricted?<p className="mt-3 text-sm text-slate-500">Team analytics are restricted for this role.</p>:data.team.items.length?<div className="mt-4 grid gap-3 sm:grid-cols-2">{data.team.items.map(item=><article key={item.user_id} className="rounded-xl border p-4"><strong>{item.display_name||'Practitioner'}</strong><p className="mt-2 text-sm text-slate-600">{item.active_clients} active assignments · {item.sessions} sessions</p></article>)}</div>:<p className="mt-3 text-sm text-slate-500">Confirmed empty: no active team workload records.</p>}</section>
  </div>
}
